#!/bin/bash
# Task 135-w7-golden-m2-fp -- meshsim sim/ WORKER7 (branch sim-w7 fb6f21e). Not a timing task.
# golden-m2's full-size references again at fb6f21e, whose .fp files carry the D12 header (configuration, inputs):
# regen.sh ALL=1 '^sort64k' (5 runs, 3 at a time), every file kept in $DATA/w7-golden-m2/fb6f21e (staged, then moved;
# COMPLETE). Checks against Quest 134's set in $DATA/w7-golden-m2/f47b12f: every file's sha256 equal except
# sort64k-fp.fp, whose lines other than '#' must be identical (the same fingerprints); writes the new HASHES.
# Expected ~8 min. Writes only results/135-w7-golden-m2-fp/ and $DATA/w7-golden-m2/fb6f21e. Safe to re-run.
set -u
cd "$(dirname "$0")/.."
REPO=$PWD; RES=$REPO/results/135-w7-golden-m2-fp; mkdir -p "$RES"
W=/tmp/w7-135; rm -rf "$W"; mkdir -p "$W"; trap 'rm -rf "$W"' EXIT
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "fa3f099d7d96b565378e7015e5a6505e554d421061a56430ace81ef9d9b8845d" ] || { echo "kit sha256 mismatch"; exit 2; }
mkdir -p "$W/kit" && tar -xzf "$W/kit.tgz" -C "$W/kit" || exit 2
DATA=$HOME/data
{ mkdir -p "$DATA" && touch "$DATA/.writable" && rm -f "$DATA/.writable"; } 2>/dev/null || DATA=$REPO/data
OLD=$DATA/w7-golden-m2/f47b12f; DEST=$DATA/w7-golden-m2/fb6f21e; echo "$DEST" > "$RES/data_path.txt"
verdict() { echo "VERDICT $1: $2"; }
{
[ -f "$OLD/COMPLETE" ] && verdict "Quest 134's set present" PASS || { verdict "Quest 134's set present" FAIL; exit 1; }
G=$W/kit/sim/tests/golden-m2
rm -rf "$DEST.staging"; mkdir -p "$DEST.staging"
(cd "$G" && KEEP="$DEST.staging" ALL=1 P=3 JX=-Xmx5g ./regen.sh '^sort64k') > "$RES/regen-full.log" 2>&1; tail -2 "$RES/regen-full.log"
(cd "$DEST.staging" && sha256sum *) > "$RES/files.sha256"; cat "$RES/files.sha256"
n=0; bad=0
while read -r h f; do
  n=$((n + 1)); o=$(awk -v f="$f" '$2 == f {print $1}' "$OLD/COMPLETE")
  if [ "$f" = sort64k-fp.fp ]; then
    if cmp -s <(grep -v '^#' "$DEST.staging/$f") <(grep -v '^#' "$OLD/$f"); then echo "$f: fingerprints identical to 134's (header new)"; else echo "$f: FINGERPRINTS DIFFER"; bad=1; fi
  elif [ "$h" = "$o" ]; then echo "$f: SAME as 134"; else echo "$f: DIFF from 134"; bad=1; fi
done < "$RES/files.sha256"
[ $n = 11 ] && [ $bad = 0 ] && verdict "11 files, 10 identical to 134's, sort64k-fp.fp's fingerprints identical" PASS || verdict "comparison with 134 ($n files)" FAIL
head -80 "$DEST.staging/sort64k-fp.fp" | grep '^#' > "$RES/sort64k-fp.header.txt"
cp "$G/HASHES" "$RES/HASHES"
cp "$RES/files.sha256" "$DEST.staging/COMPLETE"; rm -rf "$DEST"; mv "$DEST.staging" "$DEST"
} 2>&1 | tee "$RES/run.log"
grep -q '^VERDICT .*: FAIL' "$RES/run.log" && exit 1
exit 0
